  "labels": [
    {
      "label": "T_Grinding",
      "span": "If you like making an army from scratch, training, building, gathering resources then you may like this game. If you expected puzzles such as those in the ads for this game, you'll be doing chores in order to get to them.",
      "rule_applied": "definition",
      "rationale": "The player must perform resource gathering, training, building, and other chore-like tasks to reach the puzzle content, describing tedious activity required for progress."
